package com.ke.ticketsystemke.service;import com.ke.ticketsystemke.dto.*;import com.ke.ticketsystemke.entity.*;import com.ke.ticketsystemke.repository.*;import com.ke.ticketsystemke.storage.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.mock.web.MockMultipartFile;import org.springframework.test.util.ReflectionTestUtils;import java.io.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class)class WarrantyAttachmentServiceTest{@Mock TicketRepository tickets;@Mock WarrantyClaimRepository claims;@Mock WarrantyReplacementRepository replacements;@Mock WarrantyAttachmentRepository attachments;@Mock EmployeeRepository employees;@Mock AccessService access;@Mock WarrantyClaimEventService audit;@Mock WarrantyFileStorage storage;@Mock WarrantyDocumentRequirementService requirements;WarrantyAttachmentService service;Ticket ticket;WarrantyClaim claim;
@BeforeEach void setup(){service=new WarrantyAttachmentService(tickets,claims,replacements,attachments,employees,access,audit,storage,requirements,1000,20,10);ticket=new Ticket();ticket.setId(1L);claim=new WarrantyClaim();ReflectionTestUtils.setField(claim,"id",2L);claim.setTicket(ticket);claim.setActive(true);when(tickets.findById(1L)).thenReturn(Optional.of(ticket));when(claims.findById(2L)).thenReturn(Optional.of(claim));}
@Test void validJpegStoresMetadataAndAudits()throws Exception{byte[] jpeg={(byte)0xff,(byte)0xd8,(byte)0xff,1};var file=new MockMultipartFile("file","bill.jpg","text/plain",jpeg);when(storage.store(eq(2L),any())).thenReturn(new WarrantyFileStorage.StoredFile("claims/2/uuid",4,"a".repeat(64)));when(attachments.saveAndFlush(any())).thenAnswer(i->{WarrantyAttachment a=i.getArgument(0);ReflectionTestUtils.setField(a,"id",9L);ReflectionTestUtils.setField(a,"version",0L);return a;});WarrantyAttachmentResponse out=service.upload(1L,2L,WarrantyAttachmentCategory.BILL_IMAGE,null,file,"ADMIN");assertThat(out.detectedMimeType()).isEqualTo("image/jpeg");assertThat(out.toString()).doesNotContain("claims/2/uuid");verify(audit).record(eq(claim),eq(WarrantyClaimEventType.WARRANTY_ATTACHMENT_UPLOADED),anyString(),anyString(),anyMap());}
@Test void rejectsUnsupportedAndMismatchedFiles(){var exe=new MockMultipartFile("file","bad.exe","application/octet-stream",new byte[]{1,2,3});assertThatThrownBy(()->service.upload(1L,2L,WarrantyAttachmentCategory.BILL_IMAGE,null,exe,"ADMIN")).hasMessageContaining("415");var pngAsJpg=new MockMultipartFile("file","bad.jpg","image/jpeg",new byte[]{(byte)137,80,78,71,13,10,26,10});assertThatThrownBy(()->service.upload(1L,2L,WarrantyAttachmentCategory.BILL_IMAGE,null,pngAsJpg,"ADMIN")).hasMessageContaining("415");verifyNoInteractions(storage);}
@Test void replacementCategoryRequiresMatchingReplacement(){var pdf=new MockMultipartFile("file","proof.pdf","application/pdf","%PDF-1.4".getBytes());assertThatThrownBy(()->service.upload(1L,2L,WarrantyAttachmentCategory.REPLACEMENT_PROOF,null,pdf,"ADMIN")).hasMessageContaining("400");WarrantyClaim other=new WarrantyClaim();ReflectionTestUtils.setField(other,"id",3L);WarrantyReplacement r=new WarrantyReplacement();ReflectionTestUtils.setField(r,"id",4L);r.setWarrantyClaim(other);when(replacements.findById(4L)).thenReturn(Optional.of(r));assertThatThrownBy(()->service.upload(1L,2L,WarrantyAttachmentCategory.REPLACEMENT_PROOF,4L,pdf,"ADMIN")).hasMessageContaining("404");}
@Test void databaseFailureDeletesStoredFile()throws Exception{var pdf=new MockMultipartFile("file","bill.pdf","application/pdf","%PDF-1.4".getBytes());var stored=new WarrantyFileStorage.StoredFile("claims/2/key",8,"b".repeat(64));when(storage.store(eq(2L),any())).thenReturn(stored);when(attachments.saveAndFlush(any())).thenThrow(new RuntimeException("db"));assertThatThrownBy(()->service.upload(1L,2L,WarrantyAttachmentCategory.BILL_IMAGE,null,pdf,"ADMIN")).hasMessageContaining("503");verify(storage).deletePermanent("claims/2/key");}}
